function updateDesktopDisplayReadout() {
  const el = document.getElementById("display-current");
  if (!el) return;
  const t = desktopDisplayCopy();
  el.textContent = `${t.current}：${screen.w} × ${screen.h}`;
}
function openDesktopDisplay() {
  if (!desktopDisplay) return;
  cancelControl();
  closeWindow("system");
  const t = desktopDisplayCopy(),
    w = makeWindow("display", t.title, "system-window display-window");
  const label = document.createElement("label"),
    select = document.createElement("select");
  label.htmlFor = "desktop-resolution";
  label.textContent = t.resolution;
  select.id = "desktop-resolution";
  for (const value of desktopResolutionPresets) {
    const option = document.createElement("option");
    option.value = value;
    option.textContent = value.replace("x", " × ");
    select.append(option);
  }
  select.value = desktopDisplay.value;
  const current = document.createElement("p");
  current.id = "display-current";
  const help = document.createElement("p");
  help.textContent = t.help;
  const status = document.createElement("p");
  status.id = "display-save-status";
  status.setAttribute("role", "status");
  status.textContent = t.saved;
  const apply = (value) => {
    status.textContent = desktopDisplay.set(value) ? t.saved : t.temporary;
    select.value = desktopDisplay.value;
    resize();
  };
  select.onchange = () => apply(select.value);
  const reset = document.createElement("button");
  reset.id = "display-reset";
  reset.textContent = t.reset;
  reset.onclick = () => apply("1600x900");
  const fullscreen = document.createElement("button");
  fullscreen.id = "display-fullscreen";
  fullscreen.textContent = t.fullscreen;
  fullscreen.onclick = toggleGameFullscreen;
  const hint = document.createElement("p");
  hint.id = "display-fullscreen-hint";
  w.body.append(label, select, current, help, reset, fullscreen, hint, status);
  updateDesktopDisplayReadout();
  syncDesktopFullscreen();
}

function manualCastPriority(m, spell) {
  return (
    m.job === "Wizard" &&
    (m.assist?.autoMagic === true || m.assist?.autoShield === true) &&
    !toggledSpells.has(spell) &&
    !armedSpells.has(spell)
  );
}
async function startupJSON(url, timeout = 8000) {
  for (let attempt = 0; attempt < 2; attempt++) {
    const controller = new AbortController(),
      timer = setTimeout(() => controller.abort(), timeout);
    try {
      const response = await fetch(url, { signal: controller.signal });
      if (!response.ok) throw Error("Resource " + response.status + ": " + url);
      return await response.json();
    } catch (error) {
      if (attempt === 1) {
        globalThis.backmirStartup?.fail(error);
        throw error;
      }
    } finally {
      clearTimeout(timer);
    }
  }
}



