function officialGameAccessWindow() {
  cancelControl();
  installOfficialAccessStyles();
  const t = officialAccessCopy(),
    config = officialGameAccessConfig(),
    w = makeWindow("official-access", t.title, "system-window official-access-window");
  if (!mobileMode) {
    w.el.style.width = "480px";
    w.el.style.maxWidth = "calc(100% - 16px)";
  }
  const statement = document.createElement("p");
  statement.className = "official-description";
  statement.textContent = t.statement;
  const nav = document.createElement("nav");
  nav.className = "official-links";
  nav.setAttribute("aria-label", t.title);
  const status = document.createElement("p");
  status.className = "official-status";
  status.setAttribute("role", "status");
  let navigating = false;
  for (const [key, path] of config.links) {
    const link = document.createElement("a");
    link.href = new URL(path, config.home).href;
    link.textContent = t[key];
    link.dataset.officialLink = key;
    link.onclick = async (event) => {
      if (event.button !== 0 || event.ctrlKey || event.metaKey || event.shiftKey || event.altKey)
        return;
      event.preventDefault();
      if (navigating) return;
      navigating = true;
      status.textContent = t.saving;
      try {
        await accept(await api("save", {}));
        location.assign(link.href);
      } catch {
        status.textContent = t.saveError;
        navigating = false;
      }
    };
    nav.append(link);
  }
  for (const [key, action] of [
    ["cloud", () => cloudAccountWindow()],
    [
      "update",
      () => {
        systemMenu();
        document.querySelector("#force-update")?.focus();
      },
    ],
  ]) {
    const button = document.createElement("button");
    button.type = "button";
    button.textContent = t[key];
    button.dataset.officialAction = key;
    button.onclick = () => {
      closeWindow("official-access");
      action();
    };
    nav.append(button);
  }
  const address = document.createElement("label");
  address.className = "official-address";
  address.textContent = t.address;
  address.htmlFor = "official-site-address";
  const row = document.createElement("div");
  row.className = "official-address-row";
  const input = document.createElement("input");
  input.id = "official-site-address";
  input.readOnly = true;
  input.value = config.home;
  input.setAttribute("aria-label", t.address);
  const copy = document.createElement("button");
  copy.type = "button";
  copy.textContent = t.copy;
  copy.onclick = async () => {
    try {
      if (!navigator.clipboard?.writeText) throw Error("clipboard");
      await navigator.clipboard.writeText(input.value);
      status.textContent = t.copied;
    } catch {
      input.focus();
      input.select();
      input.setSelectionRange(0, input.value.length);
      status.textContent = t.manual;
    }
  };
  row.append(input, copy);
  const hint = document.createElement("p");
  hint.className = "official-hint";
  hint.textContent = t.linkHint;
  const details = document.createElement("details"),
    summary = document.createElement("summary");
  summary.textContent = t.help;
  details.append(summary);
  for (const text of [t.browser, t.desktop, t.save]) {
    const p = document.createElement("p");
    p.textContent = text;
    details.append(p);
  }
  const version = document.createElement("p");
  version.className = "official-hint";
  version.textContent =
    t.version + "：" + (document.querySelector('meta[name="dream-version"]')?.content || "—");
  w.body.append(statement, nav, address, row, status, hint, details, version);
  return w;
}



