  if (stamp === inventoryStamp) return;
  inventoryStamp = stamp;
  const nextBag = JSON.stringify(shared);
  const nextHotbar = JSON.stringify([
    quickbarItems(m).map((item) => (item ? [item.uid, item.id, item.count] : null)),
    m.skills.map((skill) => [skill.Spell, skill.Key, skill.Info?.Icon, skill.Info?.Name]),
  ]);
  if (nextHotbar !== hotbarStamp) {
    hotbarStamp = nextHotbar;
    hotbar();
  }
  if (nextBag !== bagStamp) {
    bagStamp = nextBag;
    if ($("#win-bag")) openWindow("bag", true);
  }
