async function accountAction(route, data) {
  if (route === "start" && mobile && !mobile.canStart()) {
    $("#status").textContent = mobile.startMessage();
    say(mobile.startMessage());
    return false;
  }
  if (entryBusy || controlModeSwitching) return false;
  entryBusy = true;
  const enter = $("#enter-role");
  if (route === "start") {
    globalThis.backmirTelemetry?.entryBegin();
    enter.disabled = true;
    enter.textContent = i18n.t("entry.loading");
    $("#status").textContent = i18n.t("entry.loading");
  }
  try {
    if (route === "start") {
      await syncBeforeRoleStart(data);
      await loadGameResources();
    }
    await accept(await api(route, data));
    return true;
  } catch (e) {
    if (route === "start") globalThis.backmirTelemetry?.loadFailure("entry");
    $("#account-error").textContent = e.message;
    $("#status").textContent = e.message;
    say(e.message);
    return false;
  } finally {
    entryBusy = false;
    enter.disabled = !entryRole;
    enter.textContent = i18n.t("entry.enter");
  }
}
async function leaveCharacter() {
  cancelControl();
  await command("LogOut");
  if (state.stage === "Game") {
    say(i18n.t("ui.d743143a4878"));
    return false;
  }
  closeNPC();
  $("#windows").innerHTML = "";
  await flushCloudBeforeLeave();
  return true;
}

