  const hasDescription = book
    ? d.DreamUsage || (/\p{Script=Han}/u.test(d.ToolTip || "") ? d.ToolTip : "")
    : d.DreamUsage || d.ToolTip || d.DreamRawItem?.Desc;
  const description = hasDescription ? i18n.entity("items", d.Index, "description") : "";
