let forgeSelection = { Mode: "dismantle" },
  forgePage = "dismantle",
  forgeCraftSection = "skills",
  forgeMaterialSlot = 0;
let cubeSlots = Array(8).fill(null),
  cubeQuoteVersion = 0,
  cubeQuotePending = false,
  cubeQuoteQueued = false;
const cubeItem = (uid) =>
  [...(state.me?.inventory || []), ...(state.me?.questInventory || [])].find((i) => i?.uid === uid);
function renderCubeQuestMaterials() {
  const list = $("#win-forge .cube-quest-materials");
  if (!list) return;
  const inputs = new Set(
    forgeConfig.recipes
      .filter((r) => r.mode === "pandora")
      .flatMap((r) => r.inputs.map((i) => i.item)),
  );
  const materials = (state.me.questInventory || []).filter((i) => i && inputs.has(i.id));
  list.parentElement.hidden = !materials.length;
  list.replaceChildren();
  for (const item of materials) {
    const b = document.createElement("button"),
      selected = cubeSlots.includes(item.uid);
    b.className = "cube-quest-material" + (selected ? " selected" : "");
    b.dataset.cubeQuestUid = item.uid;
    b.setAttribute("aria-pressed", String(selected));
    b.innerHTML =
      '<canvas width="32" height="32"></canvas><span>' +
      esc(itemName(items.get(item.id))) +
      "<small>×" +
      item.count +
      "</small></span>";
    icon(b.querySelector("canvas"), item.id);
    tip(b, itemText(item));
    b.onclick = () => {
      const at = cubeSlots.indexOf(item.uid);
      if (at >= 0) cubeSlots[at] = null;
      else {
        const empty = cubeSlots.indexOf(null);
        if (empty < 0) {
          say(i18n.t("cube.full"));
          return;
        }
        cubeSlots[empty] = item.uid;
      }
      $("#tip").hidden = true;
      quoteCube();
    };
    list.append(b);
  }
}
function refreshCubeInventory() {
  const w = $("#win-forge");
  if (!w?.classList.contains("cube-window")) return;
  const stamp = JSON.stringify([state.me.inventory, state.me.questInventory]);
  if (w.dataset.cubeInventory === stamp) return;
  w.dataset.cubeInventory = stamp;
  quoteCube();
}
function renderCubeSlots() {
  const w = $("#win-forge");
  if (!w?.classList.contains("cube-window")) return;
  w.querySelectorAll("[data-cube-slot]").forEach((slot, n) => {
    const item = cubeItem(cubeSlots[n]);
    if (!item) cubeSlots[n] = null;
    slot.replaceChildren();
    slot.onpointerenter = null;
    slot.onpointermove = null;
    slot.onpointerleave = null;
    if (item) {
      const c = document.createElement("canvas");
      c.width = c.height = 36;
      slot.append(c);
      icon(c, item.id);
      const count = document.createElement("small");
      count.textContent = item.count > 1 ? item.count : "";
      slot.append(count);
      tip(slot, itemText(item));
    }
  });
  forgeSelection = { Mode: "cube", Selected: cubeSlots.filter((uid) => uid !== null) };
  renderCubeQuestMaterials();
}
function openCube() {
  forgePage = "pandora";
  cubeSlots = Array(8).fill(null);
  cubeQuoteVersion++;
  const w = makeWindow("forge", i18n.t("cube.title"), "forge-window forge-direct cube-window");
  w.body.innerHTML = `<p class="cube-subtitle">${esc(i18n.t("cube.subtitle"))}</p><div class="cube-slots">${Array.from({ length: 8 }, (_, n) => `<button class="cube-slot" data-cube-slot="${n}" aria-label="${esc(i18n.t("cube.slot", { slot: n + 1 }))}"></button>`).join("")}</div><p class="forge-hint">${esc(i18n.t("cube.hint"))}</p><section class="cube-quest-picker" hidden><p>${esc(i18n.t("cube.questMaterials"))}</p><div class="cube-quest-materials"></div></section><div class="forge-quote" role="status">${esc(i18n.t("cube.empty"))}</div><button class="forge-submit" disabled>${esc(i18n.t("cube.combine"))}</button>`;
  w.body.querySelectorAll("[data-cube-slot]").forEach((slot, n) => {
    slot.onclick = () => {
      cubeSlots[n] = null;
      $("#tip").hidden = true;
      quoteCube();
    };
    slot.oncontextmenu = (e) => {
      e.preventDefault();
      slot.click();
    };
  });
  w.body.querySelector(".forge-submit").onclick = async () => {
    const button = w.body.querySelector(".forge-submit");
    button.disabled = true;
    const ok = await command("Forge", forgeSelection);
    if (!w.el.isConnected) return;
    if (ok) openForge("pandora");
    else quoteCube();
  };
  refreshCubeInventory();
}
async function quoteCube() {
  const w = $("#win-forge");
  if (!w?.classList.contains("cube-window")) return;
  renderCubeSlots();
  const version = ++cubeQuoteVersion,
    button = w.querySelector(".forge-submit"),
    note = w.querySelector(".forge-quote");
  button.disabled = true;
  if (!forgeSelection.Selected.length) {
    note.textContent = i18n.t("cube.empty");
    return;
  }
  note.textContent = i18n.t("cube.checking");
  if (cubeQuotePending) {
    cubeQuoteQueued = true;
    return;
  }
  cubeQuotePending = true;
  try {
    const ok = await command("ForgeQuote", forgeSelection);
    if (!ok && w.isConnected && version === cubeQuoteVersion)
      note.textContent = i18n.t("cube.invalid");
  } finally {
    cubeQuotePending = false;
    if (cubeQuoteQueued) {
      cubeQuoteQueued = false;
      quoteCube();
    }
  }
}
const recipeTitle = (recipe) =>
  i18n.t("recipe." + recipe.id, {
    output: itemName(items.get(recipe.output.item)),
    input: itemName(items.get(recipe.inputs[0].item)),
  });
const forgeLabels = {
  identify: i18n.t("forge.mode.identify"),
  dismantle: i18n.t("forge.mode.dismantle"),
  enhance: i18n.t("forge.mode.enhance"),
  reset: i18n.t("forge.mode.reset"),
  merge: i18n.t("forge.mode.merge"),
  crystal: i18n.t("forge.mode.crystal"),
  craft: i18n.t("forge.mode.craft"),
  potential: i18n.t("forge.mode.potential"),
  awaken: i18n.t("forge.mode.awaken"),
  pandora: i18n.t("forge.mode.pandora"),
  mix: i18n.t("forge.mode.mix"),
};
function forgeItemButton(item, label) {
  const b = document.createElement("button");
  b.className = "forge-slot";
  b.setAttribute("aria-label", label || itemName(items.get(item.id)));
  b.innerHTML =
    '<canvas width="36" height="36"></canvas><small>' +
    (item.materialQuality
      ? i18n.t("forge.qualityShort", { quality: item.materialQuality })
      : item.count > 1
        ? item.count
        : "") +
    "</small>";
  icon(b.querySelector("canvas"), item.id);
  tip(b, itemText(item));
  return b;
}
// Slots refer to inventory UIDs; only the Forge command consumes items.
function renderForgeTarget() {
  const w = $("#win-forge");
  if (!w) return;
  const target = w.querySelector(".forge-target"),
    item = state.me.inventory.find((i) => i?.uid === forgeSelection.Target);
  target.replaceChildren();
  target.onpointerenter = null;
  target.onpointermove = null;
  target.onpointerleave = null;
  $("#tip").hidden = true;
  if (item) {
    const c = document.createElement("canvas");
    c.width = c.height = 36;
    target.append(c);
    icon(c, item.id);
    tip(target, itemText(item));
  }
  w.querySelector(".potential-history")?.remove();
  if (["potential", "awaken"].includes(forgePage) && item?.potentialOptions?.length) {
    const history = document.createElement("div");
    history.className = "potential-history";
    for (const [n, p] of item.potentialOptions.entries()) {
      const choose = document.createElement("button");
      choose.textContent =
        i18n.text(potentialLabelRef(p)) +
        " · " +
        Object.entries(p.stats)
          .map(
            ([k, v]) =>
              i18n.t("gear.potentialStat." + potentialStatKey(k)) +
              "+" +
              v +
              (potentialStatKey(k) === "attackSpeed" ? "" : "%"),
          )
          .join(", ");
      choose.onclick = () => {
        forgeSelection = { Mode: "potentialChoose", Target: item.uid, Choice: n };
        quoteForge();
      };
      history.append(choose);
    }
    w.querySelector(".forge-picker").append(history);
  }
}
function removeForgeTarget() {
  delete forgeSelection.Target;
  delete forgeSelection.Selected;
  inferForgeMode();
  renderForgeTarget();
  renderForgeSlots();
  quoteForge();
}
function renderForgeMix() {
  const list = $("#win-forge .forge-results");
  if (!list) return;
  list.replaceChildren();
  for (const uid of forgeSelection.Selected || []) {
    const item = state.me.inventory.find((i) => i?.uid === uid);
    if (!item) continue;
    const b = forgeItemButton(item);
    b.classList.add("selected");
    b.title = i18n.t("forge.remove");
    b.onclick = () => {
      forgeSelection.Selected = forgeSelection.Selected.filter((n) => n !== uid);
      forgeSelection.Target = forgeSelection.Selected[0];
      renderForgeTarget();
      quoteForge();
    };
    b.oncontextmenu = (e) => {
      e.preventDefault();
      b.click();
    };
    list.append(b);
  }
}
function placeForgeItem(uid, element) {
  const w = $("#win-forge"),
    item = w?.classList.contains("cube-window")
      ? cubeItem(uid)
      : state.me?.inventory.find((i) => i?.uid === uid),
    def = item && items.get(item.id);
  if (!w || !def) return;
  if (w.classList.contains("cube-window")) {
    const slot = element.closest("[data-cube-slot]");
    if (!slot) {
      say(i18n.t("forge.dragCube"));
      return;
    }
    if (item.id === forgeConfig.boxId) {
      say(i18n.t("forge.keepCube"));
      return;
    }
    const n = Number(slot.dataset.cubeSlot),
      old = cubeSlots.indexOf(uid);
    if (old >= 0) cubeSlots[old] = null;
    cubeSlots[n] = uid;
    quoteCube();
    return;
  }
  const stone = element.closest("[data-forge-material]"),
    target = element.closest(".forge-target");
  if (!stone && !target) {
    say(i18n.t("forge.dragSlot"));
    return;
  }
  if (stone) {
    if (forgePage === "dismantle") {
      say(i18n.t("forge.outputSlotHint"));
      return;
    }
    if (def.Type !== "ForgeMaterial") {
      say(i18n.t("forge.stoneOnly"));
      return;
    }
    forgeMaterialSlot = Number(stone.dataset.forgeMaterial);
    forgeSelection.Material = uid;
  } else {
    if (!(def.Type in equipSlots)) {
      say(i18n.t("forge.equipmentOnly"));
      return;
    }
    if (
      ["potential", "awaken"].includes(forgePage) &&
      !item.handmade &&
      !def.DreamRawItem?.Handmake
    ) {
      say(i18n.t("forge.handmadeOnly"));
      return;
    }
    if (forgePage === "mix") {
      forgeSelection.Selected ??= [];
      if (!forgeSelection.Selected.includes(uid)) forgeSelection.Selected.push(uid);
      forgeSelection.Target = forgeSelection.Selected[0];
    } else forgeSelection.Target = uid;
  }
  inferForgeMode();
  renderForgeTarget();
  renderForgeSlots();
  quoteForge();
}
// The five native upper slots hold one selected stone, or dismantling outputs.
function inferForgeMode() {
  const item = state.me.inventory.find((i) => i?.uid === forgeSelection.Material),
    def = item && items.get(item.id);
  if (["enhance", "reset", "merge", "crystal"].includes(forgePage))
    forgeSelection.Mode =
      item?.id === forgeConfig.resetId
        ? "reset"
        : (def?.DreamName || def?.Name || "").startsWith("凝晶石")
          ? "crystal"
          : !forgeSelection.Target && forgeConfig.essences.some((e) => e.item === item?.id)
            ? "merge"
            : "enhance";
  if (["potential", "awaken"].includes(forgePage))
    forgeSelection.Mode = forgeConfig.crafting.talents[item?.id] ? "awaken" : "potential";
}
function renderForgeSlots(outputs = []) {
  const w = $("#win-forge");
  if (!w) return;
  const material = state.me.inventory.find((i) => i?.uid === forgeSelection.Material);
  w.querySelectorAll("[data-forge-material]").forEach((slot, n) => {
    slot.replaceChildren();
    const row =
      forgePage === "dismantle"
        ? outputs[n]
        : n === forgeMaterialSlot && material
          ? { item: material.id, count: material.count }
          : null;
    if (row) {
      const c = document.createElement("canvas");
      c.width = c.height = 32;
      slot.append(c);
      icon(c, row.item);
      const label = document.createElement("small");
      label.textContent = row.count;
      slot.append(label);
      tip(
        slot,
        itemText(
          material && forgePage !== "dismantle"
            ? material
            : { id: row.item, count: row.count, added: {} },
        ),
      );
    } else {
      slot.onpointerenter = null;
      slot.onpointermove = null;
      slot.onpointerleave = null;
    }
    slot.classList.toggle("selected", forgePage !== "dismantle" && n === forgeMaterialSlot);
  });
}


function openForge(mode = "dismantle", recipeId = null) {
  const focusRecipe = recipeId && forgeConfig.recipes.find((recipe) => recipe.id === recipeId);
  if (focusRecipe) forgeCraftSection = focusRecipe.handmade ? "equipment" : "materials";
  if (!forgeInterfaceEnabled) {
    say(i18n.t("forge.closed"));
    return;
  }
  if (!mobileMode) cancelControl();
  cancelBagCarry();
  setItemMode("use");
  if (!$("#win-bag")) openWindow("bag");
  $("#win-npc")?.remove();
  $("#tip").hidden = true;
  forgePage = mode;
  forgeSelection = { Mode: mode };
  if (["pandora", "mix"].includes(mode)) {
    openCube();
    return;
  }
  const hand = ["craft", "awaken", "potential"].includes(mode),
    upgrade = ["enhance", "reset", "merge", "crystal"].includes(mode);
  const recipesPage = mode === "craft";
  const previous = $("#win-forge"),
    position = previous?.style.cssText;
  const w = makeWindow(
    "forge",
    i18n.t("forge.title"),
    "forge-window" + (recipesPage ? "" : " forge-direct"),
  );
  if (position) w.el.style.cssText = position;
  const tabs = [
    ["dismantle", i18n.t("forge.mode.dismantle")],
    ["enhance", i18n.t("forge.applyEssence")],
    ["craft", i18n.t("forge.mode.craft")],
  ];
  w.body.innerHTML =
    '<nav class="forge-tabs">' +
    tabs
      .map(
        ([k, n]) =>
          '<button data-forge-tab="' +
          k +
          '" class="' +
          (k === mode || (k === "craft" && hand) || (k === "enhance" && upgrade) ? "active" : "") +
          '">' +
          n +
          "</button>",
      )
      .join("") +
    '</nav><nav class="forge-subtabs"></nav><div class="forge-layout"><div class="forge-workbench"><div class="forge-chamber"><div class="forge-results"></div><button class="forge-target" aria-label="' +
    esc(i18n.t("forge.target")) +
    '">' +
    esc(mobile?.chooseItem() || i18n.t("forge.dragEquipment")) +
    '</button></div><div class="forge-quote" role="status">' +
    esc(mobile?.forgeHint() || i18n.t("forge.initial")) +
    '</div><div class="forge-outcome"></div><button class="forge-submit" disabled>' +
    forgeLabels[mode] +
    '</button></div><div class="forge-picker"></div></div>';
  w.body.querySelectorAll("[data-forge-tab]").forEach(
    (b) =>
      (b.onclick = () => {
        if (b.dataset.forgeTab === "craft") forgeCraftSection = "skills";
        openForge(b.dataset.forgeTab);
      }),
  );
  const sub = w.body.querySelector(".forge-subtabs");
  const subtabs = hand
    ? [
        ["skills", i18n.t("forge.tab.skills")],
        ["materials", i18n.t("forge.tab.materials")],
        ["equipment", i18n.t("forge.tab.equipment")],
        ["potential", i18n.t("forge.tab.potential")],
      ]
    : [];
  for (const [k, n] of subtabs) {
    const b = document.createElement("button");
    b.textContent = n;
    b.classList.toggle(
      "active",
      k === mode ||
        (mode === "awaken" && k === "potential") ||
        (mode === "craft" && k === forgeCraftSection),
    );
    b.onclick = () => {
      if (["skills", "materials", "equipment"].includes(k)) {
        forgeCraftSection = k;
        openForge("craft");
      } else openForge(k);
    };
    sub.append(b);
  }
  const native = mode === "dismantle" || upgrade,
    two = ["potential", "awaken"].includes(mode);
  if (native || two) {
    const chamber = w.body.querySelector(".forge-chamber"),
      results = chamber.querySelector(".forge-results"),
      target = chamber.querySelector(".forge-target");
    chamber.classList.add(native ? "forge-native" : "forge-two-slot");
    chamber.after(results);
    results.classList.add("forge-explanation");
    for (let n = 0; n < (native ? 5 : 1); n++) {
      const slot = document.createElement("button");
      slot.className = "forge-stone";
      slot.dataset.forgeMaterial = n;
      slot.setAttribute(
        "aria-label",
        i18n.t(mode === "dismantle" ? "forge.outputSlot" : "forge.materialSlot", { slot: n + 1 }),
      );
      slot.title =
        mode === "dismantle" ? i18n.t("forge.salvageOutput") : i18n.t("forge.chooseSlot");
      slot.onclick = () => {
        if (mode === "dismantle") return;
        forgeMaterialSlot = n;
        renderForgeSlots();
      };
      slot.oncontextmenu = (e) => {
        e.preventDefault();
        delete forgeSelection.Material;
        $("#tip").hidden = true;
        inferForgeMode();
        renderForgeSlots();
        quoteForge();
      };
      chamber.append(slot);
    }
    if (two) {
      forgeMaterialSlot = 0;
      const arrow = document.createElement("span");
      arrow.className = "forge-arrow";
      arrow.textContent = "→";
      chamber.append(arrow);
    }
    const fee = document.createElement("div");
    fee.className = "forge-native-cost";
    fee.textContent = i18n.t("forge.cost", { gold: 0 });
    chamber.append(fee);
    target.textContent = "";
    const hint = document.createElement("p");
    hint.className = "forge-hint";
    hint.textContent =
      mode === "dismantle"
        ? i18n.t("forge.salvageHint")
        : upgrade
          ? i18n.t("forge.enhanceHint")
          : i18n.t("forge.potentialHint");
    chamber.before(hint);
    renderForgeSlots();
  }
  const picker = w.body.querySelector(".forge-picker");
  const target = w.body.querySelector(".forge-target");
  target.dataset.emptyLabel = i18n.t("forge.emptyEquipment");
  target.title = i18n.t("forge.targetHint");
  target.onclick = removeForgeTarget;
  target.oncontextmenu = (e) => {
    e.preventDefault();
    removeForgeTarget();
  };
  if (mode === "craft" && forgeCraftSection === "skills") {
    w.body.querySelector(".forge-layout").classList.add("forge-skills-layout");
    w.body.querySelector(".forge-workbench").hidden = true;
    for (const [k, n] of Object.entries(forgeConfig.crafting.names)) {
      const s = state.me.crafting?.skills?.[k] || { level: 0, xp: 0 },
        max = k === "equipment" ? 10 : 9,
        table = forgeConfig.crafting.experienceBySkill?.[k] || forgeConfig.crafting.experience,
        need = table[Math.min(table.length - 1, Math.max(0, s.level - 1))];
      const row = document.createElement("div");
      row.className = "forge-skill";
      row.innerHTML =
        "<div>" +
        esc(i18n.t("forge.skillLevel", { skill: i18n.entity("crafting", k), level: s.level })) +
        '</div><progress max="' +
        need +
        '" value="' +
        (s.level >= max ? need : s.xp) +
        '"></progress><small>' +
        (s.level >= max ? i18n.t("gear.maxLevel") : s.xp + " / " + need) +
        "</small>";
      picker.append(row);
    }
    const note = document.createElement("p");
    note.textContent =
      (state.me.crafting?.stage || 0) < 1
        ? i18n.t("forge.apprentice")
        : state.me.crafting.stage === 1
          ? i18n.t("forge.apprenticeEquipment")
          : i18n.t("forge.craftHint");
    picker.append(note);
    return;
  }
  if (mode === "craft") {
    w.body.querySelector(".forge-target").hidden = true;
    const filter = document.createElement("select");
    filter.setAttribute("aria-label", i18n.t("forge.category"));
    filter.innerHTML = (
      forgeCraftSection === "materials"
        ? [
            ["all", i18n.t("forge.allMaterials")],
            ["ore", i18n.entity("crafting", "ore")],
            ["wood", i18n.entity("crafting", "wood")],
            ["gem", i18n.entity("crafting", "gem")],
            ["cloth", i18n.entity("crafting", "cloth")],
            ["talent", i18n.t("forge.talentRecipe")],
          ]
        : [
            ["all", i18n.t("forge.allEquipment")],
            ["Weapon", i18n.enum("ItemType", "Weapon")],
            ["Armour", i18n.enum("ItemType", "Armour")],
            ["Helmet", i18n.enum("ItemType", "Helmet")],
            ["Amulet", i18n.enum("ItemType", "Amulet")],
            ["Stone", i18n.t("forge.medalStone")],
            ["Necklace", i18n.enum("ItemType", "Necklace")],
            ["Bracelet", i18n.enum("ItemType", "Bracelet")],
            ["Ring", i18n.enum("ItemType", "Ring")],
            ["Belt", i18n.enum("ItemType", "Belt")],
            ["Boots", i18n.enum("ItemType", "Boots")],
          ]
    )
      .map(([k, n]) => '<option value="' + k + '">' + n + "</option>")
      .join("");
    picker.append(filter);
    const search = document.createElement("input");
    search.placeholder = i18n.t("forge.searchPlaceholder");
    search.setAttribute("aria-label", i18n.t("forge.searchAria"));
    picker.append(search);
    const list = document.createElement("div");
    list.className = "forge-recipe-list";
    picker.append(list);
    const recipes = forgeConfig.recipes.filter(
      (r) =>
        r.mode === mode &&
        (mode !== "craft" || (forgeCraftSection === "materials" ? !r.handmade : !!r.handmade)),
    );
    function renderRecipes() {
      list.innerHTML = "";
      for (const recipe of recipes) {
        const d = items.get(recipe.output.item),
          materials = recipe.inputs
            .map((i) => itemName(items.get(i.item)) + "×" + i.count)
            .join("、");
        if (
          (filter.value !== "all" && ![recipe.skill, d.Type].includes(filter.value)) ||
          !(recipeTitle(recipe) + " " + materials + " " + recipe.name)
            .normalize("NFKC")
            .toLocaleLowerCase(i18n.locale)
            .includes(search.value.trim().normalize("NFKC").toLocaleLowerCase(i18n.locale))
        )
          continue;
        const b = document.createElement("button");
        b.className = "forge-recipe";
        b.dataset.recipe = recipe.id;
        b.innerHTML =
          '<canvas width="36" height="36"></canvas><span>' +
          esc(recipeTitle(recipe)) +
          "<small>" +
          esc(
            recipe.skill && recipe.skill !== "talent"
              ? i18n.t("forge.skillLevel", {
                  skill: i18n.entity("crafting", recipe.skill),
                  level: recipe.level,
                })
              : i18n.t("forge.mode.pandora"),
          ) +
          "</small></span>";
        icon(b.querySelector("canvas"), d.Index);
        tip(b, itemText({ id: d.Index, added: {}, count: 1 }));
        b.onclick = () => {
          list.querySelectorAll("button").forEach((x) => x.classList.toggle("active", x === b));
          forgeSelection = { Mode: "recipe", Recipe: recipe.id, Count: 1 };
          quoteForge();
        };
        list.append(b);
      }
    }
    filter.onchange = renderRecipes;
    search.oninput = renderRecipes;
    renderRecipes();
    if (focusRecipe) {
      const focus = [...list.querySelectorAll("[data-recipe]")].find(
        (b) => b.dataset.recipe === recipeId,
      );
      if (focus) {
        focus.click();
        focus.scrollIntoView({ block: "nearest" });
      }
    }
  }
  const submit = w.body.querySelector(".forge-submit");
  submit.onclick = async () => {
    const recipeId = forgeSelection.Recipe;
    submit.disabled = true;
    const ok = await command("Forge", forgeSelection);
    if (!submit.isConnected) return;
    if (ok) openForge(mode, recipeId);
    else quoteForge();
  };
}
async function quoteForge() {
  const w = $("#win-forge");
  if (!w) return;
  w.querySelector(".forge-submit").disabled = true;
  w.querySelector(".forge-results").replaceChildren();
  w.querySelector(".forge-outcome").textContent = "";
  const fee = w.querySelector(".forge-native-cost");
  if (fee) fee.textContent = i18n.t("forge.cost", { gold: "—" });
  if (forgePage === "dismantle") renderForgeSlots();
  if (forgePage === "mix" && (forgeSelection.Selected?.length || 0) < 3) {
    renderForgeMix();
    w.querySelector(".forge-quote").textContent = i18n.t("forge.mixCount", {
      count: forgeSelection.Selected?.length || 0,
    });
    return;
  }
  if (
    ["potential", "awaken", "enhance", "crystal", "merge"].includes(forgeSelection.Mode) &&
    !forgeSelection.Material
  ) {
    w.querySelector(".forge-quote").textContent = i18n.t("forge.selectStone");
    return;
  }
  if (forgeSelection.Target || ["merge", "recipe"].includes(forgeSelection.Mode)) {
    const ok = await command("ForgeQuote", forgeSelection);
    if (!ok && w.isConnected)
      w.querySelector(".forge-quote").textContent = i18n.t("forge.invalidSelection");
  } else w.querySelector(".forge-quote").textContent = i18n.t("forge.selectEquipment");
}


function showForgeQuote(q) {
  const w = $("#win-forge");
  if (!w) return;
  if (w.classList.contains("cube-window")) {
    if (JSON.stringify(q.cubeSelection) !== JSON.stringify(forgeSelection.Selected)) return;
    if (q.error) {
      w.querySelector(".forge-quote").textContent = i18n.text(q.error);
      w.querySelector(".forge-submit").disabled = true;
      return;
    }
    w.querySelector(".forge-quote").textContent =
      i18n.text(q.description) +
      "\n" +
      i18n.t("forge.cost", { gold: i18n.number(q.gold) }) +
      (q.canForge ? "" : i18n.t("forge.shortage"));
    w.querySelector(".forge-submit").disabled = !q.canForge;
    return;
  }
  if (q.cubeSelection) return;
  w.querySelector(".forge-quote").textContent =
    i18n.text(q.description) +
    (q.requirement ? "\n" + i18n.text(q.requirement) : "") +
    "\n" +
    i18n.t("forge.costBalance", { gold: i18n.number(q.gold), balance: i18n.number(state.me.gold) });
  const list = w.querySelector(".forge-results");
  list.innerHTML = "";
  renderForgeSlots(q.mode === "dismantle" ? q.outputs : []);
  const fee = w.querySelector(".forge-native-cost");
  if (fee) fee.textContent = i18n.t("forge.cost", { gold: i18n.number(q.gold) });
  const note = w.querySelector(".forge-outcome");
  note.textContent =
    (q.outputQuality ? i18n.t("forge.outputQuality", { quality: q.outputQuality }) : "") +
    (q.outputStars !== undefined
      ? i18n.t("forge.outputStars", {
          quality: i18n.t("quality." + q.outputStars),
          stars: q.outputStars,
        })
      : "");
  if (q.recipe) {
    const skill = q.recipe.skill,
      progress = state.me.crafting?.skills?.[skill];
    if (progress && skill !== "talent") {
      const table =
        forgeConfig.crafting.experienceBySkill?.[skill] || forgeConfig.crafting.experience;
      const xp =
        progress.level >= (skill === "equipment" ? 10 : 9)
          ? i18n.t("gear.maxLevel")
          : progress.xp + " / " + table[progress.level - 1];
      w.querySelector(".forge-quote").textContent +=
        "\n" + i18n.t("forge.currentSkillProgress", { skill: i18n.entity("crafting", skill), xp });
    }
    if (q.canForge)
      forgeSelection.Ingredients = q.allocations.map((a) => ({ uid: a.uid, count: a.count }));
    if (q.recipe.processing) {
      const count = document.createElement("select");
      count.setAttribute("aria-label", i18n.t("forge.batchSize"));
      count.innerHTML = [1, 2, 3, 4, 5]
        .map(
          (n) =>
            '<option value="' + n + '">' + esc(i18n.t("forge.batch", { count: n })) + "</option>",
        )
        .join("");
      count.value = forgeSelection.Count || 1;
      count.onchange = () => {
        forgeSelection.Count = Number(count.value);
        delete forgeSelection.Ingredients;
        quoteForge();
      };
      list.append(count);
      const hint = document.createElement("p");
      hint.className = "forge-processing-hint";
      hint.textContent = i18n.t("forge.processingHint", {
        count: q.processingInputs || Number(count.value),
        output: q.outputs.reduce((n, row) => n + row.count, 0),
        experience: (q.recipe.experience || 1) * (q.processingInputs || Number(count.value)),
      });
      list.append(hint);
    }
    const used = (q.allocations || []).flatMap((a) => Array(a.count).fill(a.uid));
    const selectors = [];
    for (const row of q.inputs)
      for (let unit = 0; unit < row.count; unit++) {
        const candidates = [...state.me.inventory, ...(state.me.questInventory || [])].filter(
            (i) => i?.id === row.item,
          ),
          wrap = document.createElement("div");
        wrap.className = "forge-material-slot";
        wrap.innerHTML = '<canvas width="36" height="36"></canvas>';
        icon(wrap.querySelector("canvas"), row.item);
        const select = document.createElement("select");
        select.setAttribute(
          "aria-label",
          i18n.t("forge.materialNumber", { item: itemName(items.get(row.item)), number: unit + 1 }),
        );
        select.innerHTML =
          '<option value="">' +
          esc(i18n.t("forge.missingItem", { item: itemName(items.get(row.item)) })) +
          "</option>" +
          candidates
            .map(
              (i) =>
                '<option value="' +
                i.uid +
                '">' +
                esc(itemName(items.get(i.id))) +
                " · " +
                (i.materialQuality
                  ? i18n.t("forge.materialQuality", { quality: i.materialQuality })
                  : i18n.t("forge.stars", { stars: exceptionalPoints(i) })) +
                " · #" +
                i.uid +
                "</option>",
            )
            .join("");
        const at = used.findIndex((uid) => candidates.some((i) => i.uid === uid));
        if (at >= 0) {
          select.value = used[at];
          used.splice(at, 1);
        }
        selectors.push(select);
        select.onchange = () => {
          const counts = new Map();
          for (const s of selectors)
            if (s.value) counts.set(Number(s.value), (counts.get(Number(s.value)) || 0) + 1);
          forgeSelection.Ingredients = [...counts].map(([uid, count]) => ({ uid, count }));
          quoteForge();
        };
        wrap.append(select);
        const chosen = candidates.find((i) => i.uid === Number(select.value));
        if (chosen) tip(wrap, itemText(chosen));
        list.append(wrap);
      }
  } else if (q.mode === "mix") renderForgeMix();
  if (!w.querySelector(".forge-native"))
    for (const [kind, rows] of [
      [i18n.t("forge.input"), q.recipe ? [] : q.inputs],
      [i18n.t("forge.output"), q.outputs],
    ])
      for (const row of rows) {
        const b = document.createElement("div");
        b.className = "forge-preview";
        b.innerHTML =
          '<canvas width="36" height="36"></canvas><span>' +
          kind +
          " " +
          esc(itemName(items.get(row.item))) +
          " ×" +
          row.count +
          "</span>";
        icon(b.querySelector("canvas"), row.item);
        tip(
          b,
          itemText({ id: row.item, added: {}, count: row.count, materialQuality: q.outputQuality }),
        );
        list.append(b);
      }
  const button = w.querySelector(".forge-submit");
  button.textContent =
    q.mode === "recipe"
      ? i18n.t("forge.make")
      : q.mode === "potentialChoose"
        ? i18n.t("forge.choosePotential")
        : forgeLabels[q.mode];
  button.disabled = !q.canForge;
}
function updateBossTimers() {
  const run = state.me?.challenge;
  let countdown = $("#challenge-countdown");
  if (run && !countdown) {
    countdown = document.createElement("div");
    countdown.id = "challenge-countdown";
    countdown.setAttribute("role", "timer");
    $("#stage").append(countdown);
  }
  const challengeText = run
    ? i18n.t(run.cleared ? "map.challengeLootTimer" : "map.challengeTimer", {
        seconds: Math.ceil(run.remainingMs / 1000),
        wave: run.wave,
      })
    : "";
  if (countdown) {
    countdown.hidden = !run;
    if (countdown.textContent !== challengeText) countdown.textContent = challengeText;
  }
  const panel = $("#win-map");
  if (!panel) return;
  let list = panel.querySelector(".boss-timers");
  if (!list) {
    list = document.createElement("div");
    list.className = "boss-timers";
    panel.querySelector(".body")?.append(list);
  }
  list.textContent = [
    ...(state.me?.trialRun
      ? [
          i18n.t("map.trialTimer", {
            floor: state.me.trialRun.floor,
            minutes: Math.ceil(state.me.trialRun.remainingMs / 60000),
            honor: state.me.trial?.honor || 0,
          }),
        ]
      : []),
    ...(challengeText ? [challengeText] : []),
    ...(state.me?.bossRespawns || []).map(
      (b) =>
        i18n.entity("monsters", b.definition) +
        ": " +
        i18n.t(b.alive >= b.cap ? "map.bossAlive" : "map.bossTimer", {
          alive: b.alive,
          cap: b.cap,
          seconds: Math.ceil(b.remainingMs / 1000),
        }) +
        (b.positions?.length
          ? " · " + b.positions.map((p) => "(" + p.x + ", " + p.y + ")").join(" / ")
          : ""),
    ),
  ].join("; ");
}
