function scarletSwordWindow(data) {
  const w = makeWindow("scarlet", i18n.t("late.scarletSelect"), "forge-window"),
    selected = new Map();
  const intro = document.createElement("p");
  intro.textContent = i18n.t("late.scarletHint");
  w.body.append(intro);
  const result = document.createElement("p");
  result.textContent = i18n.t("late.scarletResult", { item: itemName(items.get(data.Result)) });
  w.body.append(result);
  const preview = document.createElement("div");
  preview.className = "forge-quote";
  for (const material of data.Materials) {
    const d = items.get(material.item),
      row = document.createElement("label");
    row.style.display = "block";
    row.textContent = itemName(d) + " × " + material.count + " ";
    if (d.Type === "Weapon") {
      const select = document.createElement("select");
      select.setAttribute("aria-label", itemName(d));
      const empty = document.createElement("option");
      empty.value = "";
      empty.textContent = i18n.t("late.selectEquipment");
      select.append(empty);
      for (const item of state.me.inventory.filter(
        (i) => i?.id === material.item && !i.bound && !i.locked,
      )) {
        const option = document.createElement("option");
        option.value = item.uid;
        option.textContent =
          i18n.t("late.bagSlot", { slot: state.me.inventory.indexOf(item) + 1 }) +
          " · " +
          itemName(d) +
          (exceptionalPoints(item) ? " · " + exceptionalPoints(item) + "★" : "");
        select.append(option);
      }
      select.onchange = () => {
        const uid = Number(select.value) || 0;
        selected.set(material.item, uid);
        const item = state.me.inventory.find((i) => i?.uid === uid);
        preview.innerHTML = item ? itemText(item) : "";
      };
      row.append(select);
    } else {
      const count = state.me.inventory
        .filter((i) => i?.id === material.item)
        .reduce((n, i) => n + i.count, 0);
      row.append(document.createTextNode(i18n.t("late.have", { count })));
    }
    w.body.append(row);
  }
  w.body.append(preview);
  const submit = document.createElement("button");
  submit.textContent = i18n.t("late.exchange");
  submit.onclick = async () => {
    submit.disabled = true;
    const ok = await command("ExchangeScarletSword", {
      Selected: [...selected.values()].filter(Boolean),
    });
    if (!w.el.isConnected) return;
    if (ok) w.el.remove();
    else submit.disabled = false;
  };
  w.body.append(submit);
}

