accountSession.subscribe((session) => {
  // A network refresh failure keeps the current account space and offline play.
  if (session.status === "checking" || session.status === "unavailable") {
    if (cloudSync.owner === undefined) {
      cloudSync.restoreLocalOwner();
      if (cloudSync.owner) gameAuto.emit("offlineAccount");
      queueMicrotask(() => ensureGameCloudContext());
    }
    renderGameAccount();
    return;
  }
  const owner = session.status === "member" ? session.user.id : null;
  cloudSync.setAccount(owner);
  gameAuto.setUser(owner);
  renderGameAccount();
  queueMicrotask(async () => {
    await ensureGameCloudContext();
    if (gameAuto.user && cloudSync.contextOwner === owner) gameAuto.tick();
  });
  observeBackupPrompt();
  if (cloudPanel) queueMicrotask(() => cloudPanel.refresh());
});


let postAuthCloudTask = null;
async function completeGameSignIn(source = "cloud_panel") {
  if (!cloudSync.autoBindGuest) {
    ensureGameCloudContext();
    gameAuto.request(0);
    cloudPanel?.refresh();
    return;
  }
  const owner = gameAuto.user,
    generation = cloudSync.generation;
  const valid = () =>
    !!owner &&
    cloudSync.valid(owner, generation) &&
    gameAuto.user === owner &&
    gameAuto.enabled(owner) &&
    accountSession.state.status === "member" &&
    accountSession.state.user?.id === owner;
  if (!valid()) return;
  if (postAuthCloudTask?.owner === owner && postAuthCloudTask.generation === generation)
    return postAuthCloudTask.promise;
  const me = state?.stage === "Game" ? state.me : null,
    previousOwner = state?.sync?.ownerId;
  const resume =
    me?.cloudId && (previousOwner === null || previousOwner === owner) ? me.cloudId : null;
  const task = { owner, generation, promise: null };
  postAuthCloudTask = task;
  task.promise = (async () => {
    // Only an explicit login success enters this workflow. Ordinary session
    // refreshes keep the current game and its account partition untouched.
    await gameAuto.exclusive(async () => {
      if (!valid()) return;
      if (state.stage === "Game") {
        cancelControl();
        await command("LogOut");
        if (!valid()) return;
        if (state.stage === "Game") throw Error("pendingSelection");
      }
      await cloudSync.context(owner);
      if (!valid()) return;
      gameAuto.hold = null;
    });
    if (!valid()) return;
    // The exclusive gate must be released before starting the uploader.
    await gameAuto.syncNow({ flush: true });
    if (!valid()) return;
    if (
      ["firstLoad", "conflict", "mergeFull", "guestBinding", "upgradeRequired"].includes(
        gameAuto.hold,
      )
    ) {
      if (state.stage === "Select") cloudAccountWindow(source);
      return;
    }
    if (
      resume &&
      state.stage === "Select" &&
      state.sync?.ownerId === owner &&
      ["uploaded", "unchanged", "downloaded"].includes(gameAuto.status.code)
    ) {
      const role = state.roles.find((role) => role.cloudId === resume);
      // Resume this exact character using normal re-entry rules (including the
      // existing return-to-town snapshot), never an arbitrary account character.
      if (role && valid() && (!mobile || mobile.canStart()))
        await accountAction("start", { id: role.id });
    }
    cloudPanel?.refresh();
  })().finally(() => {
    if (postAuthCloudTask === task) postAuthCloudTask = null;
  });
  return task.promise;
}
function cloudAccountWindow(source = "cloud_panel") {
  cancelControl();
  closeNPC();
  cloudPanel?.dispose();
  const w = makeWindow(
    "cloud",
    accountPresentation(accountSession.state, i18n.locale).title,
    "system-window cloud-window",
  );
  cloudPanelWindow = w;
  const exclusive = (action) => gameAuto.exclusive(action);
  const panel = mountCloudSavePanel(w.body, {
    locale: i18n.locale,
    jobs,
    user: () => accountSession.state.user,
    status: () => gameAuto.status,
    load: async () => {
      await accountSession.refresh();
      const view = await cloudSync.view();
      if (!accountSession.state.user && cloudSync.owner)
        view.owner = { displayName: cloudPanelMessages(i18n.locale).savedAccount };
      return view;
    },
    sync: async () => {
      const returning = state.stage === "Game",
        owner = cloudSync.owner,
        generation = cloudSync.generation;
      try {
        await exclusive(async () => {
          if (state.stage === "Game") {
            await command("LogOut");
            if (state.stage === "Game") throw Error("pendingSelection");
          }
          await cloudSync.context();
          // Release the manual gate before invoking the uploader.
          gameAuto.hold = null;
        });
        await gameAuto.syncNow({ flush: true });
      } finally {
        // Logout closes game windows. Continue this explicit workflow in a fresh
        // panel after context verification, without reviving a disposed panel.
        if (
          returning &&
          owner === cloudSync.owner &&
          generation === cloudSync.generation &&
          state.stage === "Select" &&
          !cloudPanelWindow?.el.isConnected
        )
          cloudAccountWindow(source);
      }
    },
    resolve: (choices) =>
      exclusive(() =>
        cloudSync.binding ? cloudSync.resolveBinding(choices) : cloudSync.resolve(choices),
      ),
    bind: () => exclusive(() => cloudSync.bind()),
    setEnabled: (enabled) => {
      gameAuto.setEnabled(enabled);
      gameAuto.request(0);
    },
    renameDevice: (name) => exclusive(() => cloudSync.renameDevice(name)),
    exportLocal: async () =>
      (
        await localAPI(
          "cloud/prepare",
          { build: document.querySelector('meta[name="dream-build"]')?.content },
          eventCursor,
        )
      ).saveJson,
    exportCloud: async () => {
      const owner = gameAuto.user,
        listing = await siteCloud.list(owner);
      return (await siteCloud.read(owner, listing.headRevision)).save.saveJson;
    },
    exportMergeLocal: async () =>
      (await localAPI("cloud/export-backup", { kind: "local" }, eventCursor)).saveJson,
    exportMergeRemote: async () =>
      (await localAPI("cloud/export-backup", { kind: "remote" }, eventCursor)).saveJson,
    rollback: () => exclusive(() => cloudSync.rollback()),
    loadCloud: () => exclusive(() => cloudSync.loadCloud()),
    restoreRecovery: (id) => exclusive(() => cloudSync.restoreRecovery(id)),
    update: () =>
      document.dispatchEvent(new CustomEvent("backmir-update-request", { cancelable: true })),
    itemName: (item) => itemName(items.get(item.id)),
    questName: (id) => i18n.entity("quests", id),
    emailBindingMount: (host) =>
      accountSession.state.emailLoginAvailable
        ? mountEmailBinding(host, {
            user: accountSession.state.user,
            locale: i18n.locale,
            onSuccess: () => cloudPanel?.refresh(),
          })
        : null,
    loginMount: async (host) => {
      const session = await accountSession.refresh();
      accountTrack("account_view", { source }, true);
      let completed;
      const mounted = await mountAccountLogin(host, {
        locale: i18n.locale,
        source,
        track: accountTrack,
        emailEnabled: session.emailLoginAvailable,
        googleEnabled: session.googleAvailable,
        onSuccess: () =>
          (completed ??= completeGameSignIn(source).catch((error) => {
            say(error.message);
            cloudPanel?.refresh();
          })),
      });
      if (mobile)
        requestAnimationFrame(() => host.scrollIntoView?.({ block: "start", behavior: "smooth" }));
      return mounted;
    },
    onChange: ({ type }) => {
      if (type === "continue") {
        panel.dispose();
        if (cloudPanel === panel) cloudPanel = null;
        if (cloudPanelWindow === w) cloudPanelWindow = null;
        w.el.remove();
      }
    },
  });
  cloudPanel = panel;
  const cleanup = new MutationObserver(() => {
    if (!w.el.isConnected) {
      panel.dispose();
      if (cloudPanel === panel) cloudPanel = null;
      if (cloudPanelWindow === w) cloudPanelWindow = null;
      cleanup.disconnect();
    }
  });
  cleanup.observe(document.getElementById("windows"), { childList: true });
}
function gameLeaderboardWindow() {
  cancelControl();
  closeNPC();
  const m = leaderboardMessages(i18n.locale),
    w = makeWindow("leaderboard", m.title, "leaderboard-window");
  const toolbar = document.createElement("div");
  toolbar.className = "game-lb-toolbar";
  const tabs = document.createElement("nav");
  tabs.className = "game-lb-tabs";
  tabs.setAttribute("aria-label", m.title);
  let selectedBoard = "all";
  for (const key of ["all", "Warrior", "Wizard", "Taoist"]) {
    const tab = document.createElement("button");
    tab.type = "button";
    tab.textContent = m[key];
    tab.dataset.board = key;
    tab.setAttribute("aria-pressed", String(key === selectedBoard));
    tab.onclick = () => {
      selectedBoard = key;
      for (const el of tabs.children) el.setAttribute("aria-pressed", String(el === tab));
      load();
    };
    tabs.append(tab);
  }
  const refresh = document.createElement("button");
  refresh.type = "button";
  refresh.textContent = m.refresh;
  refresh.className = "game-lb-refresh";
  toolbar.append(tabs, refresh);
  const mine = document.createElement("p");
  mine.className = "game-lb-mine";
  const status = document.createElement("p");
  status.className = "game-lb-status";
  status.setAttribute("role", "status");
  const scroll = document.createElement("div");
  scroll.className = "game-lb-scroll";
  const table = document.createElement("table");
  table.className = "game-lb-table";
  table.setAttribute("aria-label", m.title);
  const head = table.createTHead().insertRow();
  for (const key of ["rank", "name", "job", "level", "xp"]) {
    const th = document.createElement("th");
    th.scope = "col";
    th.textContent = m[key];
    head.append(th);
  }
  const list = table.createTBody();
  scroll.append(table);
  const details = document.createElement("details");
  details.className = "game-lb-details";
  const summary = document.createElement("summary");
  summary.textContent = m.details;
  const intro = document.createElement("p");
  intro.textContent = m.rules + " " + m.disclosure;
  const participation = document.createElement("div");
  participation.className = "game-lb-participation";
  const link = document.createElement("a");
  link.textContent = m.open;
  link.href = i18n.path("/Game/leaderboard/");
  link.target = "_blank";
  link.rel = "noopener";
  details.append(summary, intro, participation, link);
  w.body.replaceChildren(toolbar, mine, status, scroll, details);
  let generation = 0,
    busy = false,
    refreshPending = false;
  const button = (label, action) => {
    const el = document.createElement("button");
    el.type = "button";
    el.textContent = label;
    el.onclick = action;
    participation.append(el);
    return el;
  };
  const note = (value) => {
    const el = document.createElement("p");
    el.textContent = value;
    participation.append(el);
  };
  async function request(path, data) {
    const response = await fetch(path, {
      method: data ? "POST" : "GET",
      credentials: "same-origin",
      cache: "no-store",
      signal: AbortSignal.timeout(10000),
      headers: {
        "X-Backmir-Language": i18n.locale,
        ...(data ? { "Content-Type": "application/json", "X-Backmir-Community": "1" } : {}),
      },
      body: data ? JSON.stringify(data) : undefined,
    });
    const result = await response.json();
    if (!response.ok)
      throw Error(
        result.errorCode ||
          (response.status === 401
            ? "auth"
            : response.status === 409
              ? "accountChanged"
              : "unavailable"),
      );
    return result;
  }
  async function change(enabled, owner) {
    if (busy) return;
    busy = true;
    generation++;
    w.body.querySelectorAll("button,select").forEach((el) => (el.disabled = true));
    status.textContent = m.loading;
    try {
      await request("/Game/api/leaderboard/participation", {
        enabled,
        consentVersion: 2,
        accountId: owner,
      });
      await load();
      if (accountSession.state.user?.id === owner && w.el.isConnected)
        status.textContent = enabled ? m.joined : m.left;
    } catch (error) {
      status.textContent = m[error.message] || m.unavailable;
    } finally {
      busy = false;
      w.body.querySelectorAll("button,select").forEach((el) => (el.disabled = false));
      if (refreshPending) {
        refreshPending = false;
        load();
      }
    }
  }
  async function load() {
    const run = ++generation;
    status.textContent = m.loading;
    participation.replaceChildren();
    try {
      const session = await accountSession.refresh();
      if (session.status === "unavailable") throw Error("unavailable");
      const owner = session.user?.id;
      const data = await request("/Game/api/leaderboard?board=" + encodeURIComponent(selectedBoard));
      if (run !== generation || !w.el.isConnected || accountSession.state.user?.id !== owner)
        return;
      mine.textContent = data.mine
        ? `${m.mine}: #${data.mine.rank} · ${data.mine.name} · ${m.level} ${data.mine.level}`
        : data.participation?.enabled
          ? m[data.participation.state] || m.noClass
          : m.notJoined;
      list.replaceChildren();
      if (!data.signedIn || !owner) button(m.signin, cloudAccountWindow);
      else if (!data.participation?.enabled) {
        if (data.hasCloudSave) {
          note(m.consent);
          button(m.join, () => change(true, owner)).dataset.lbJoin = "";
        } else {
          note(m.noCloudSave);
          button(m.cloudOpen, cloudAccountWindow);
        }
      } else {
        if (data.hasCloudSave && data.participation.state === "waiting") {
          note(m.consent);
          button(m.join, () => change(true, owner)).dataset.lbJoin = "";
        }
        button(m.leave, () => change(false, owner)).dataset.lbLeave = "";
      }
      for (const row of data.rows) {
        const tr = list.insertRow();
        if (row.id === data.mine?.id) tr.className = "game-lb-self";
        const rank = tr.insertCell();
        rank.textContent = String(row.rank);
        if (row.rank <= 3) rank.className = "game-lb-medal";
        const name = tr.insertCell();
        name.textContent = row.name;
        name.title = row.name;
        tr.insertCell().textContent = m[row.job];
        tr.insertCell().textContent = String(row.level);
        const xp = tr.insertCell(),
          label = document.createElement("span");
        label.textContent = row.nextXP ? Math.floor((row.xp / row.nextXP) * 100) + "%" : m.max;
        xp.append(label);
        if (row.nextXP) {
          const progress = document.createElement("progress");
          progress.max = row.nextXP;
          progress.value = row.xp;
          progress.setAttribute("aria-label", m.xp);
          progress.title = row.xp + " / " + row.nextXP;
          xp.append(progress);
        }
      }
      details.open = !data.participation?.enabled && !!data.signedIn;
      status.textContent = data.rows.length ? "" : m.empty;
    } catch (error) {
      if (run === generation) status.textContent = m[error.message] || m.unavailable;
    }
  }
  let identity = accountSession.state.status + ":" + (accountSession.state.user?.id || "");
  const unsubscribe = accountSession.subscribe((session) => {
    if (!w.el.isConnected) {
      queueMicrotask(() => unsubscribe());
      return;
    }
    const key = session.status + ":" + (session.user?.id || "");
    if (key === identity) return;
    identity = key;
    generation++;
    participation.replaceChildren();
    mine.textContent = "";
    if (busy) refreshPending = true;
    else queueMicrotask(load);
  });
  refresh.onclick = load;
  load();
}



let entryBusy = false,
  entryRole = 0,
  entryJob = "Warrior",
  entryGender = "Male",
  entryInitialized = false;

function updateEntryPreview() {
  const art = $("#create-character-art");
  art.src = "/Game/assets/entry/" + entryJob + "-" + entryGender + ".webp";
  art.alt = jobs[entryJob] + " · " + i18n.t(entryGender === "Male" ? "entry.male" : "entry.female");
  $("#gender").value = entryGender;
  $("#job-description").textContent = i18n.t("entry.description." + entryJob);
  for (const b of $("#jobs").querySelectorAll("[data-job]")) {
    const active = b.dataset.job === entryJob;
    b.setAttribute("aria-pressed", String(active));
    b.style.backgroundImage =
      "url(/Game/assets/entry/" + b.dataset.job + (active ? "-selected" : "") + ".webp)";
  }
  for (const b of $("#sex-buttons").querySelectorAll("button")) {
    const active = b.dataset.gender === entryGender;
    b.setAttribute("aria-pressed", String(active));
    b.style.backgroundImage =
      "url(/Game/assets/entry/" + b.dataset.gender + (active ? "-selected" : "") + ".webp)";
  }
}
function renderNativeRoles() {
  if (!entryInitialized) {
    entryInitialized = true;
    bindEntryUI();
  }
  const roles = state.roles || [],
    stamp = JSON.stringify(roles);
  if (rolesStamp === stamp) return;
  rolesStamp = stamp;
  if (!roles.some((r) => r.id === entryRole)) entryRole = roles.at(-1)?.id || 0;
  $("#roles").innerHTML = roles
    .map(
      (r) =>
        '<button data-role="' +
        r.id +
        '" aria-pressed="' +
        (entryRole === r.id) +
        '">' +
        esc(i18n.t("entry.role", { name: r.name, job: jobs[r.job], level: r.level })) +
        "</button>",
    )
    .join("");
  for (const b of $("#roles").querySelectorAll("button")) {
    b.onclick = () => {
      entryRole = Number(b.dataset.role);
      rolesStamp = null;
      renderNativeRoles();
    };
    b.ondblclick = () => accountAction("start", { id: Number(b.dataset.role) });
  }
  const selected = roles.find((r) => r.id === entryRole);
  $("#selected-character-art").hidden = !selected;
  if (selected) {
    $("#selected-character-art").src =
      "/Game/assets/entry/" + selected.job + "-" + selected.gender + ".webp";
    $("#selected-character-art").alt = selected.name + " · " + jobs[selected.job];
  }
  $("#entry-delete-role").disabled = !selected;
  $("#entry-delete-role").hidden = !selected;
  $("#enter-role").disabled = !selected;
  $("#enter-role").hidden = !selected;
  $("#new-role").classList.toggle("entry-primary", !selected);
  $("#entry-title").textContent = selected
    ? i18n.t("entry.selected", { name: selected.name })
    : i18n.t("entry.first");
  $("#status").textContent = gameAccountSummary() + " · " + gameCloudStatusText();
}
function bindEntryUI() {
  mountOfficialGameEntry($("#entry"));
  if (!$("#entry .language-picker")) $("#entry").append(i18n.picker({ applyNow: true }));
  if (mobileMode || i18n.locale !== "zh-CN") {
    for (const b of $("#jobs").querySelectorAll("[data-job]")) b.textContent = jobs[b.dataset.job];
    for (const b of $("#sex-buttons").querySelectorAll("button"))
      b.textContent = i18n.t(b.dataset.gender === "Male" ? "entry.male" : "entry.female");
    $("#random-job").textContent = "?";
  }
  $("#new-role").onclick = () => {
    $("#new-character").hidden = false;
    $("#entry-error").textContent = "";
    $("#name").focus();
    updateEntryPreview();
  };
  $("#cancel-create").onclick = () => {
    $("#new-character").hidden = true;
  };
  if (!$("#entry-cloud")) {
    const b = document.createElement("button");
    b.id = "entry-cloud";
    b.textContent = accountPresentation(accountSession.state, i18n.locale).button;
    b.onclick = cloudAccountWindow;
    $("#entry-saves").after(b);
  }
  if (!$("#entry-delete-role")) {
    const del = document.createElement("button");
    del.id = "entry-delete-role";
    del.type = "button";
    del.textContent = i18n.t("entry.deleteRole");
    del.onclick = confirmEntryRoleDeletion;
    $("#roles").after(del);
  }
  $("#entry-saves").onclick = systemMenu;
  $("#enter-role").onclick = () => entryRole && accountAction("start", { id: entryRole });
  for (const b of $("#jobs").querySelectorAll("[data-job]"))
    b.onclick = () => {
      entryJob = b.dataset.job;
      updateEntryPreview();
    };
  for (const b of $("#sex-buttons").querySelectorAll("button"))
    b.onclick = () => {
      entryGender = b.dataset.gender;
      updateEntryPreview();
    };
  $("#random-job").style.backgroundImage = "url(/Game/assets/entry/Random.webp)";
  $("#random-job").onclick = () => {
    entryJob = ["Warrior", "Wizard", "Taoist"][Math.floor(Math.random() * 3)];
    updateEntryPreview();
  };
  $("#confirm-create").onclick = async () => {
    const b = $("#confirm-create");
    b.disabled = true;
    $("#entry-error").textContent = "";
    try {
      if (
        await accountAction("create", {
          name: $("#name").value,
          job: entryJob,
          gender: entryGender,
        })
      ) {
        $("#new-character").hidden = true;
        $("#name").value = "";
        entryRole = state.roles.at(-1)?.id;
        rolesStamp = null;
        renderNativeRoles();
        if (entryRole) await accountAction("start", { id: entryRole });
      } else $("#entry-error").textContent = $("#account-error").textContent;
    } finally {
      b.disabled = false;
    }
  };
  $("#name").onkeydown = (e) => {
    if (e.key === "Enter") {
      e.preventDefault();
      $("#confirm-create").click();
    }
  };
  updateEntryPreview();
  mountEntryGamePresentation();
}

// Reuse native deletion and cloud tombstones, with an explicit named confirmation.
function confirmEntryRoleDeletion() {
  const role = state.stage === "Select" && state.roles.find((r) => r.id === entryRole);
  if (!role || entryBusy || controlModeSwitching) return;
  const identity = { id: role.id, cloudId: role.cloudId },
    w = makeWindow("delete-role", i18n.t("entry.deleteRole"), "system-window");
  w.body.innerHTML =
    "<p>" +
    esc(i18n.t("entry.deleteHint", { name: role.name })) +
    "</p><label>" +
    esc(i18n.t("entry.deleteTypeName")) +
    '<input data-delete-role-name autocomplete="off" maxlength="12"></label><button data-delete-role-confirm disabled>' +
    esc(i18n.t("entry.deleteRole")) +
    "</button><button data-delete-role-cancel>" +
    esc(i18n.t("entry.close")) +
    "</button>";
  const input = w.body.querySelector("[data-delete-role-name]"),
    yes = w.body.querySelector("[data-delete-role-confirm]");
  let busy = false;
  input.oninput = () => {
    yes.disabled = busy || input.value !== role.name;
  };
  w.body.querySelector("[data-delete-role-cancel]").onclick = () => {
    if (!busy) w.el.remove();
  };
  yes.onclick = async () => {
    if (
      busy ||
      input.value !== role.name ||
      state.stage !== "Select" ||
      entryBusy ||
      controlModeSwitching
    )
      return;
    const current = state.roles.find(
      (r) => r.id === identity.id && r.cloudId === identity.cloudId && r.name === role.name,
    );
    if (!current) {
      w.el.remove();
      return;
    }
    busy = true;
    yes.disabled = true;
    input.disabled = true;
    try {
      if (await accountAction("delete", identity)) {
        rolesStamp = null;
        renderNativeRoles();
        w.el.remove();
      }
    } finally {
      busy = false;
      input.disabled = false;
      input.oninput();
    }
  };
  input.focus();
}

