function mobileShareEquipment(uid, ownerId) {
  const me = state?.me;
  if (!me || me.id !== ownerId) return;
  const item = [...me.inventory, ...me.equipment].find((item) => item?.uid === uid);
  if (item && equipmentShareable(item)) return shareEquipment(item);
}
async function mobileShareCharacter(ownerId) {
  if (!state?.me || state.me.id !== ownerId) return;
  const existing = $("#win-character");
  if (existing?.querySelector(".char-layout")) return shareCharacter();
  openWindow("character", true);
  const created = $("#win-character");
  try {
    // shareCharacter clones the native layout synchronously, then repaints the
    // fixed-size paperdoll on the mounted card before rasterizing it. A hidden
    // M2 native window is never itself measured or captured as the share image.
    return await shareCharacter();
  } finally {
    if (created?.isConnected && $("#win-character") === created) created.remove();
  }
}
async function drawPetPortrait(canvas, pet) {
  const binding = compat.monsterBindings[pet.art],
    pose = binding?.actions.stand;
  if (!pose?.count) return false;
  const index = monsterFrameIndex(binding, pose, 0, 0);
  await ensureSheet(binding.pack, index);
  const image = frame(binding.pack, index);
  if (!image) return false;
  const scale = Math.min(canvas.width / image.width, canvas.height / image.height);
  const width = image.width * scale,
    height = image.height * scale,
    ctx = canvas.getContext("2d");
  ctx.imageSmoothingEnabled = false;
  ctx.drawImage(
    image.bitmap,
    image.sx,
    image.sy,
    image.width,
    image.height,
    (canvas.width - width) / 2,
    canvas.height - height,
    width,
    height,
  );
  return true;
}
async function bootMobile() {
  const { mountMobile } = await import("/Game/mobile/entry.1c52ab2efa5a.js");
  mobile = await mountMobile({
    preserveInspectionAttack: true,
    inspectionCombatHud: true,
    locale: i18n.locale,
    canvas,
    state: () =>
      activeSharedStorage && state.me
        ? { ...state, me: { ...state.me, storage: state.sharedStorage } }
        : state,
    sharedStorageActive: () => activeSharedStorage,
    now: () => performance.now(),
    command,
    dispatch: dispatchCommand,
    selected: (id) => {
      selected = id;
    },
    say,
    t: (key) => i18n.t(key),
    ready,
    melee: meleeSpell,
    direction,
    cost: (s) => skillCost(s.Info, s.EffectiveLevel ?? s.Level, state.me.stats),
    preload: preloadSpell,
    path: (goal) => world && findPath(world, state.me, goal, occupied()),
    worldReady: () => world?.id === state?.me?.map,
    adventure: () => adventureWorld,
    closePanels: () => {
      closeWindow("instance-exit");
      $("#windows").innerHTML = "";
      closeNPC();
    },
    npc: (id) => {
      npcId = id;
    },
    point: gamePoint,
    goal: (p) => ({ x: Math.floor((p.x + camera.x) / 48), y: Math.floor((p.y + camera.y) / 32) }),
    hit: (p) => hitActor(p.x + Math.round(camera.x), p.y + Math.round(camera.y)),
    viewport: (w, h, scale) => {
      screen = { w: Math.round(w / scale), h: Math.round(h / scale) };
      if (canvas.width !== screen.w) canvas.width = screen.w;
      if (canvas.height !== screen.h) canvas.height = screen.h;
    },
    pause: (paused) => localAPI("pause", { paused }, eventCursor),
    refresh: async () => accept(await localAPI("state", {}, eventCursor)),
    manageSave: async () => accept(await api("save", {})),
    open: (name) => {
      if (name === "forge") openForge();
      else if (name === "assist") openAssist();
      else if (name === "system") systemMenu();
      else openWindow(name, true);
    },
    visible: (a) => {
      const x = a.x * 48 + 24 - camera.x,
        y = a.y * 32 - camera.y;
      return x >= 0 && x <= screen.w && y >= 0 && y <= screen.h;
    },
    // Presentation-only projection follows the exact frame already painted by the actor renderer.
    actorPoint: (a) => {
      const hit = actorHits.find((h) => h.a.id === a.id),
        p = hit?.p || position(a, performance.now()),
        cx = Math.round(camera.x),
        cy = Math.round(camera.y);
      return {
        x: p.x + 24 - cx,
        y: p.y + 16 - cy,
        headY: Math.min(p.y - 56, p.y + (hit?.f?.dy ?? -48) - 10) - cy,
      };
    },
    skillDetails: (spell, body) => skillDetails(spell, { body }),
    itemName: (item) => itemName(items.get(item.id), item),
    itemText,
    icon,
    itemIcon: (c, item) => icon(c, item.id),
    actorName,
    petPortrait: drawPetPortrait,
    itemDef: (id) => items.get(id),
    equipSlots,
    setStates: (equipment) => dreamSetStates(equipment, items),
    setName: (id) => i18n.entity("sets", id),
    skillIcon,
    skillName,
    quickItems: () => quickbarItems(state.me),
    bindQuickItem,
    lockable: (item) => equipmentLockable(item, items.get(item?.id)),
    locked: equipmentLocked,
    shareable: equipmentShareable,
    shareEquipment: mobileShareEquipment,
    shareCharacter: mobileShareCharacter,
    freeSlot: (item) => freeInventorySlot(state.me, item),
    itemMode: () => itemMode,
    use: useItem,
    transfer: transferStorage,
    placeForge: placeForgeItem,
    forgeItems: (slot) =>
      state.me.inventory.filter((item) => {
        if (!item) return false;
        const def = items.get(item.id);
        return slot.matches("[data-cube-slot]")
          ? item.id !== forgeConfig.boxId
          : slot.matches("[data-forge-material]")
            ? def?.Type === "ForgeMaterial"
            : def?.Type in equipSlots;
      }),
    clearForge: (slot) => {
      if (slot.matches("[data-cube-slot]")) {
        cubeSlots[Number(slot.dataset.cubeSlot)] = null;
        quoteCube();
      } else if (slot.matches("[data-forge-material]")) {
        delete forgeSelection.Material;
        inferForgeMode();
        renderForgeSlots();
        quoteForge();
      } else removeForgeTarget();
    },
  });
}



function drawBagTicketGround(p) {
  if (!bagTicketArt.complete || !bagTicketArt.naturalWidth) return null;
  ctx.drawImage(bagTicketArt, p.x + 8, p.y - 16, 32, 32);
  return {
    bitmap: bagTicketArt,
    sx: 0,
    sy: 0,
    width: 32,
    height: 32,
    scale: 2 / 3,
    dx: 8,
    dy: -16,
  };
}

