  70: { pack: "native_weapon1", base: 38400 },
  71: { pack: "native_weapon1", base: 39600 },
  72: { pack: "native_weapon1", base: 40800 },
  73: { pack: "native_weapon1", base: 42000 },
  74: { pack: "native_weapon1", base: 43200 },
  828: { pack: "native_weapon1", base: 44400 },
  1405: { pack: "native_weapon2", base: 1200 },
